const legacyStrategySetupSlugs = new Set(["vwap_reclaim", "failed_breakout"]);

const canonicalStrategySetupTitles: Record<string, string> = {
  vwap_reclaim_long: "VWAP Reclaim Long",
  vwap_rejection_short: "VWAP Rejection Short",
  premarket_pump_short: "Premarket Pump Short",
  gap_and_crap_short: "Gap and Crap Short",
  failed_breakout_stuff: "Failed Breakout / Stuff",
  breakout_retest_long: "Breakout Retest Long",
  pullback_continuation_long: "Pullback Continuation Long",
  opening_range_breakout: "Opening Range Breakout",
  lower_high_breakdown_short: "Lower High Breakdown Short",
  liquidity_trap_reversal: "Liquidity Trap Reversal",
  crypto_smc_sweep_reclaim: "Crypto SMC Sweep + Reclaim",
};

function asRecord(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return value as Record<string, unknown>;
}

function getStrategyTemplateTitle(
  slug: string | null | undefined,
  value: StrategyI18nValue,
  fallback = ""
) {
  const normalizedSlug = (slug || "").toLowerCase();

  if (canonicalStrategySetupTitles[normalizedSlug]) {
    return canonicalStrategySetupTitles[normalizedSlug];
  }

  return getStrategyI18nText(value, "en", fallback);
}

function getStrategyI18nText(value: StrategyI18nValue, language: Language, fallback = "") {
  if (!value) return fallback;
  if (typeof value === "string") return value || fallback;

  return (
    value[language] ||
    value.en ||
    value.ru ||
    value.ua ||
    Object.values(value).find(Boolean) ||
    fallback
  );
}


