function extractCanonicalSetupNameFromText(value: string | null | undefined) {
  const text = value || "";

  for (const setupName of Object.values(canonicalStrategySetupTitles)) {
    if (text.toLowerCase().includes(setupName.toLowerCase())) {
      return setupName;
    }
  }

  return "";
}

