function getPeriodName(
  subscription: {
    period: BillingPeriod | null;
    isDemo: boolean;
  },
  t: (typeof dashboardDict)[Language]
) {
  if (subscription.isDemo) {
    return t.periods.demo;
  }

  if (!subscription.period) {
    return "вЂ”";
  }

  return t.periods[subscription.period];
}

function toNumberOrNull(value: string) {
  const cleaned = value.trim();

  if (!cleaned) {
    return null;
  }

  const numberValue = Number(cleaned.replace(",", "."));

  return Number.isFinite(numberValue) ? numberValue : null;
}

function buildEquityCurveData(trades: Trade[]) {
  return [...trades]
    .filter((trade) => trade.pnl !== null)
    .sort((a, b) => {
      const dateA = new Date(a.trade_date).getTime();
      const dateB = new Date(b.trade_date).getTime();

      if (dateA !== dateB) {
        return dateA - dateB;
      }

      return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
    })
    .reduce<
      {
        date: string;
        ticker: string;
        pnl: number;
        equity: number;
      }[]
    >((acc, trade) => {
      const previousEquity = acc.length > 0 ? acc[acc.length - 1].equity : 0;
      const pnl = trade.pnl ?? 0;

      acc.push({
        date: trade.trade_date,
        ticker: trade.ticker,
        pnl,
        equity: previousEquity + pnl,
      });

      return acc;
    }, []);
}

const DASHBOARD_COMMAND_EVENT = "skilledge:dashboard-command";

function getDashboardCommandTarget(event: Event) {
  const detail = (event as CustomEvent<{ target?: string }>).detail;
  return typeof detail?.target === "string" ? detail.target : "";
}

function scrollToDashboardElement(elementId: string, delay = 80, attempts = 10) {
  if (typeof window === "undefined") return;

  const run = (left: number) => {
    window.setTimeout(() => {
      const element = document.getElementById(elementId);

      if (element) {
        const headerOffset = 92;
        const top = element.getBoundingClientRect().top + window.scrollY - headerOffset;
        window.scrollTo({ top: Math.max(top, 0), behavior: "smooth" });
        return;
      }

      if (left > 0) {
        run(left - 1);
      }
    }, left === attempts ? delay : 120);
  };

  run(attempts);
}

function notifyDashboardCommand(target: string, delay = 80) {
  if (typeof window === "undefined") return;

  window.setTimeout(() => {
    window.dispatchEvent(
      new CustomEvent(DASHBOARD_COMMAND_EVENT, {
        detail: { target },
      })
    );
  }, delay);
}

