const loadQuickNote = async () => {
  try {
    setQuickNoteLoading(true);
    setQuickNoteError("");

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      setQuickNoteError(language === "ua" ? "РЈРІС–Р№РґРё РІ desk, С‰РѕР± Р·Р°РІР°РЅС‚Р°Р¶РёС‚Рё session note." : language === "ru" ? "Р’РѕР№РґРё РІ desk, С‡С‚РѕР±С‹ Р·Р°РіСЂСѓР·РёС‚СЊ session note." : "Enter the desk to load the session note.");
      return;
    }

    const { data, error } = await supabase
      .from("user_quick_notes")
      .select("content, updated_at")
      .eq("user_id", user.id)
      .maybeSingle();

    if (error) {
      setQuickNoteError(error.message);
      return;
    }

    setQuickNoteContent(data?.content || "");
    setQuickNoteSavedAt(data?.updated_at || "");
    setQuickNoteHydrated(true);
  } catch {
    setQuickNoteError(language === "ua" ? "Session note РЅРµ Р·Р°РІР°РЅС‚Р°Р¶РёРІСЃСЏ. РџРµСЂРµР·Р°Р№РґРё РІ desk С– РїРѕРІС‚РѕСЂРё." : language === "ru" ? "Session note РЅРµ Р·Р°РіСЂСѓР·РёР»СЃСЏ. РџРµСЂРµР·Р°Р№РґРё РІ desk Рё РїРѕРІС‚РѕСЂРё." : "Session note did not load. Re-enter the desk and retry.");
  } finally {
    setQuickNoteLoading(false);
  }
};

const saveQuickNote = async (content = quickNoteContent) => {
  try {
    setQuickNoteSaving(true);
    setQuickNoteError("");

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      setQuickNoteError(language === "ua" ? "РЈРІС–Р№РґРё РІ desk, С‰РѕР± Р·Р±РµСЂРµРіС‚Рё session note." : language === "ru" ? "Р’РѕР№РґРё РІ desk, С‡С‚РѕР±С‹ СЃРѕС…СЂР°РЅРёС‚СЊ session note." : "Enter the desk to save the session note.");
      return;
    }

    const savedAt = new Date().toISOString();

    const { error } = await supabase.from("user_quick_notes").upsert(
      {
        user_id: user.id,
        content,
        updated_at: savedAt,
      },
      { onConflict: "user_id" }
    );

    if (error) {
      setQuickNoteError(error.message);
      return;
    }

    setQuickNoteSavedAt(savedAt);
  } catch {
    setQuickNoteError(language === "ua" ? "Session note РЅРµ Р·Р±РµСЂРµР¶РµРЅРёР№. РџРµСЂРµРІС–СЂ РґРѕСЃС‚СѓРї С– РїРѕРІС‚РѕСЂРё." : language === "ru" ? "Session note РЅРµ СЃРѕС…СЂР°РЅС‘РЅ. РџСЂРѕРІРµСЂСЊ РґРѕСЃС‚СѓРї Рё РїРѕРІС‚РѕСЂРё." : "Session note was not saved. Check access and retry.");
  } finally {
    setQuickNoteSaving(false);
  }
};

