async function refreshStrategyOverview() {
  setStrategyLoading(true);
  setStrategyError("");

  try {
    const response = await authFetch("/api/strategy/overview", {
      method: "GET",
    });

    const result = await response.json().catch(() => ({}));

    if (!response.ok) {
      throw new Error(result.error || "Strategy OS did not load. Retry.");
    }

    setStrategyOverview((result || null) as StrategyOverview | null);

    try {
      const analyticsResponse = await authFetch("/api/strategy/analytics", {
        method: "GET",
      });

      const analyticsResult = await analyticsResponse.json().catch(() => ({}));

      if (analyticsResponse.ok) {
        setStrategyAnalytics((analyticsResult.analytics || null) as StrategyAnalytics | null);
      }
    } catch {
      setStrategyAnalytics(null);
    }
  } catch (error) {
    setStrategyError(
      error instanceof Error ? error.message : "Strategy OS did not load. Retry."
    );
  } finally {
    setStrategyLoading(false);
  }
}

