const handleGlobalDashboardCommand = (target: string) => {
  const setTabAndScroll = (tab: TabId, elementId?: string) => {
    setActiveTab(tab);
    updateDashboardUrlTab(tab === "alerts" ? "signals" : tab);
    notifyDashboardCommand(target, 60);

    if (elementId) {
      scrollToDashboardElement(elementId, 220, 8);
      return;
    }

    window.setTimeout(() => {
      window.scrollTo({ top: 0, behavior: "smooth" });
    }, 220);
  };

  if (target === "overview-edge") return setTabAndScroll("edge");
  if (target === "edge-dna") return setTabAndScroll("edge", "edge-dna");
  if (target === "edge-playbook") return setTabAndScroll("edge", "edge-playbook");
  if (target === "edge-rules") return setTabAndScroll("edge", "edge-rules");
  if (target === "overview-journal") return setTabAndScroll("journal", "journal-add-trade");
  if (target === "overview-reports") return setTabAndScroll("reports", "reports-performance-command");

  if (target === "journal-ticket") return setTabAndScroll("journal", "journal-add-trade");
  if (target === "journal-review") return setTabAndScroll("journal", "journal-ai-review-command");
  if (target === "journal-database") return setTabAndScroll("journal", "journal-database-command");

  if (target === "strategy-cockpit") return setTabAndScroll("strategy", "strategy-command-center");
  if (target === "strategy-library") return setTabAndScroll("strategy", "strategy-portfolio-command");
  if (target === "strategy-drill") return setTabAndScroll("strategy", "strategy-drill-command");

  if (target === "cockpit-watchlist") return setTabAndScroll("cockpit", "cockpit-watchlist");
  if (target === "cockpit-lifecycle") return setTabAndScroll("cockpit", "cockpit-lifecycle");
  if (target === "cockpit-ai") return setTabAndScroll("cockpit", "cockpit-ai");

  if (target === "charts-terminal") return setTabAndScroll("charts", "charts-terminal-command");
  if (target === "charts-watchlist") return setTabAndScroll("charts", "charts-watchlist-command");
  if (target === "charts-analysis") return setTabAndScroll("charts", "charts-analysis-command");

  if (target === "market-scan") return setTabAndScroll("market", "market-scan-command");
  if (target === "market-brief") return setTabAndScroll("market", "market-brief-command");
  if (target === "market-sources") return setTabAndScroll("market", "market-coverage-command");

  if (target === "alerts-live") return setTabAndScroll("alerts", "alerts-live-command");
  if (target === "alerts-playbook") return setTabAndScroll("alerts", "alerts-playbook-command");
  if (target === "alerts-outcomes") return setTabAndScroll("alerts", "alerts-outcomes-command");

  if (target === "coach-question") return setTabAndScroll("coach", "coach-question-command");
  if (target === "coach-history") return setTabAndScroll("coach", "coach-history-command");
  if (target === "coach-risk") return setTabAndScroll("coach", "coach-risk-command");

  if (target === "learning-path") return setTabAndScroll("learning", "learning-path-command");
  if (target === "learning-modules") return setTabAndScroll("learning", "learning-modules-command");
  if (target === "learning-progress") return setTabAndScroll("learning", "learning-path-command");

  if (target === "reports-performance") return setTabAndScroll("reports", "reports-performance-command");
  if (target === "reports-strategy") return setTabAndScroll("reports", "reports-strategy-command");
  if (target === "reports-ai") return setTabAndScroll("reports", "reports-ai-command");

  if (target === "account-access") return setTabAndScroll("billing", "account-access-command");
  if (target === "account-referral") return setTabAndScroll("billing", "account-referral-command");
  if (target === "account-plans") return setTabAndScroll("billing", "account-plans-command");

  setTabAndScroll(activeTab);
};

const getActiveTabRequiredPlan = (tabId: TabId): "edge" | "elite" | null => {
  if (tabId === "edge" && !canUseFeature(subscription.plan, "personal_edge")) {
    return "edge";
  }

  if (tabId === "strategy" && !canUseFeature(subscription.plan, "strategy_os")) {
    return "edge";
  }

  if (tabId === "learning" && !canUseFeature(subscription.plan, "learning_playbook")) {
    return "edge";
  }

  if (tabId === "reports" && !canUseFeature(subscription.plan, "ai_reports")) {
    return "edge";
  }

  if (tabId === "market" && !canUseFeature(subscription.plan, "ai_scanner")) {
    return "edge";
  }

  if ((tabId === "alerts" || tabId === "cockpit") && !canUseFeature(subscription.plan, "ai_alerts")) {
    return "elite";
  }

  return null;
};
const getTabRequiredPlanLabel = (tabId: TabId) => {
  if (!subscription.active) return "";

  const requiredPlan = getActiveTabRequiredPlan(tabId);

  if (requiredPlan === "edge") {
    return "Edge";
  }

  if (requiredPlan === "elite") {
    return "Elite";
  }

  return "";
};

