function formatAlertPrice(value?: number | null) {
  if (typeof value !== "number" || !Number.isFinite(value)) return "вЂ”";

  if (Math.abs(value) >= 100) return value.toFixed(2);
  if (Math.abs(value) >= 10) return value.toFixed(3);

  return value.toFixed(4);
}

function getAlertSourceData(alert: DashboardMarketAlert): MarketAlertSourceData {
  return alert.source_data || {};
}

function getAlertMarketStructure(alert: DashboardMarketAlert) {
  return getAlertSourceData(alert).marketStructure || null;
}

function getAlertRiskReward(alert: DashboardMarketAlert) {
  const sourceData = getAlertSourceData(alert);
  const engineRR = sourceData.skillEdgeEngine?.riskRewardRatio;

  if (typeof engineRR === "number" && Number.isFinite(engineRR)) {
    return engineRR;
  }

  const entryMin =
    typeof alert.entry_zone_min === "number" ? alert.entry_zone_min : null;
  const entryMax =
    typeof alert.entry_zone_max === "number" ? alert.entry_zone_max : null;
  const stop = typeof alert.stop_price === "number" ? alert.stop_price : null;
  const target =
    typeof alert.target_3 === "number"
      ? alert.target_3
      : typeof alert.target_2 === "number"
        ? alert.target_2
        : typeof alert.target_1 === "number"
          ? alert.target_1
          : null;

  if (entryMin === null || entryMax === null || stop === null || target === null) {
    return null;
  }

  const entry = (entryMin + entryMax) / 2;
  const direction = alert.direction === "downside" ? "downside" : "upside";

  const risk = direction === "upside" ? entry - stop : stop - entry;
  const reward = direction === "upside" ? target - entry : entry - target;

  if (risk <= 0 || reward <= 0) return null;

  return Number((reward / risk).toFixed(2));
}

function getAiValidationToneClass(tone?: SkillEdgeAiValidationUiTone | null) {
  if (tone === "premium") return "border-[#C8A96B]/22 bg-[#C8A96B]/[0.09] text-[#F4E8C8]";
  if (tone === "success") return "border-[#00C076]/22 bg-[#00C076]/[0.08] text-[#DFFFEF]";
  if (tone === "warning") return "border-[#F59E0B]/22 bg-[#F59E0B]/[0.08] text-[#FFE9BE]";
  if (tone === "danger") return "border-[#FF5A5F]/22 bg-[#FF5A5F]/[0.08] text-[#FFD7D9]";

  return "border-white/10 bg-white/[0.035] text-white/58";
}

function getAiValidationCompactPanelClass(panel: SkillEdgeAiValidationUiPanel) {
  if (!panel.available) return "border-white/10 bg-white/[0.025]";
  if (panel.deliveryEligible) return "border-[#00C076]/18 bg-[#00C076]/[0.045]";
  if (panel.verdict === "approved") return "border-[#C8A96B]/18 bg-[#C8A96B]/[0.045]";
  if (panel.verdict === "rejected") return "border-[#FF5A5F]/18 bg-[#FF5A5F]/[0.045]";
  if (panel.verdict === "needs_confirmation") return "border-[#F59E0B]/18 bg-[#F59E0B]/[0.045]";

  return "border-white/10 bg-white/[0.025]";
}

function getAiValidationCompactCopy(panel: SkillEdgeAiValidationUiPanel, language: Language) {
  const gatesPassed = panel.gates.filter((gate) => gate.passed).length;
  const gatesTotal = panel.gates.length;
  const gateText = gatesTotal > 0 ? `${gatesPassed}/${gatesTotal}` : "вЂ”";

  const deliveryText = panel.deliveryEligible
    ? language === "en"
      ? "Delivery ready"
      : language === "ua"
        ? "Р“РѕС‚РѕРІРёР№ РґРѕ РІС–РґРїСЂР°РІРєРё"
        : "Р“РѕС‚РѕРІ Рє РѕС‚РїСЂР°РІРєРµ"
    : language === "en"
      ? "Site only"
      : language === "ua"
        ? "РўС–Р»СЊРєРё СЃР°Р№С‚"
        : "РўРѕР»СЊРєРѕ СЃР°Р№С‚";

  const compactReason =
    panel.deliveryEligible
      ? panel.managementPlan[0] || panel.rrReview || panel.shortSummary
      : panel.blockedReasons[0] ||
        panel.missingConfirmations[0] ||
        panel.weakPoints[0] ||
        panel.deliveryBadge.description ||
        panel.shortSummary;

  return {
    gateText,
    deliveryText,
    compactReason,
    title:
      language === "en"
        ? "AI Validation"
        : language === "ua"
          ? "AI-РІР°Р»С–РґР°С†С–СЏ"
          : "AI-РІР°Р»РёРґР°С†РёСЏ",
    gates:
      language === "en"
        ? "Gates"
        : language === "ua"
          ? "Р“РµР№С‚Рё"
          : "Р“РµР№С‚С‹",
  };
}

