function getSignalOutcomeGradeClass(grade: SignalOutcomeGrade) {
  if (grade === "A") return "border-[#00C076]/28 bg-[#00C076]/12 text-[#DFFFEF]";
  if (grade === "B") return "border-cyan-300/24 bg-cyan-300/10 text-cyan-50";
  if (grade === "C") return "border-[#C8A96B]/28 bg-[#C8A96B]/12 text-[#F4E8C8]";
  if (grade === "AVOID") return "border-[#FF5A5F]/28 bg-[#FF5A5F]/12 text-[#FFD7D9]";
  return "border-white/10 bg-white/[0.035] text-white/56";
}

function getSignalOutcomeReactionClass(reaction: SignalReactionQuality) {
  if (reaction === "clean") return "border-[#00C076]/22 bg-[#00C076]/10 text-[#DFFFEF]";
  if (reaction === "trap") return "border-[#FF5A5F]/22 bg-[#FF5A5F]/10 text-[#FFD7D9]";
  if (reaction === "no_follow_through" || reaction === "weak") {
    return "border-[#C8A96B]/22 bg-[#C8A96B]/10 text-[#F4E8C8]";
  }
  if (reaction === "no_entry") return "border-cyan-300/18 bg-cyan-300/8 text-cyan-50/80";
  return "border-white/10 bg-white/[0.035] text-white/56";
}

function getSignalOutcomeIntelligence(
  alert: DashboardMarketAlert,
  language: Language,
  linkedTrades: Trade[] = []
) {
  const copy = getSignalOutcomeIntelligenceCopy(language);
  const status = String(alert.outcome_status || "pending").toLowerCase();
  const outcomeGroup = getAlertOutcomeGroup(alert);
  const checked =
    Boolean(alert.outcome_checked_at) ||
    typeof alert.candles_checked === "number" ||
    status !== "pending";

  const targetText = String(alert.hit_target || "").toLowerCase();
  const tp1Hit =
    targetText.includes("tp1") ||
    ["tp1_hit", "tp2_hit", "tp3_hit", "worked"].includes(status);
  const anyTargetHit = Boolean(alert.hit_target) || tp1Hit;
  const stopHit = Boolean(alert.hit_stop) || ["stopped", "stop_hit", "failed"].includes(status);
  const noEntry = status === "no_entry";
  const entryTouched =
    status === "entry_touched" ||
    Boolean(alert.hit_target) ||
    Boolean(alert.hit_stop) ||
    ["tp1_hit", "tp2_hit", "tp3_hit", "worked", "stopped", "failed"].includes(status) ||
    typeof alert.time_to_entry_minutes === "number";

  const mfe = typeof alert.mfe === "number" ? alert.mfe : null;
  const mae = typeof alert.mae === "number" ? alert.mae : null;
  const slowEntry =
    typeof alert.time_to_entry_minutes === "number" && alert.time_to_entry_minutes > 45;
  const slowTarget =
    typeof alert.time_to_target_minutes === "number" && alert.time_to_target_minutes > 180;

  const linkedReviews = linkedTrades
    .map((trade) => getSignalExecutionReview(trade))
    .filter((review): review is NonNullable<ReturnType<typeof getSignalExecutionReview>> => Boolean(review));
  const clientLateEntry = linkedReviews.some(
    (review) => review.entryInZone === false && Number(review.entryDistance || 0) > 0
  );

  let reaction: SignalReactionQuality = "pending";

  if (!checked || outcomeGroup === "pending") {
    reaction = "pending";
  } else if (noEntry || !entryTouched) {
    reaction = "no_entry";
  } else if (stopHit && !anyTargetHit) {
    reaction = "trap";
  } else if (mae !== null && mfe !== null && mae > Math.abs(mfe) * 1.25 && !anyTargetHit) {
    reaction = "trap";
  } else if (anyTargetHit && !stopHit) {
    reaction = "clean";
  } else if (entryTouched && !anyTargetHit && !stopHit && (mfe === null || mfe < 0.7)) {
    reaction = "no_follow_through";
  } else {
    reaction = "weak";
  }

  let grade: SignalOutcomeGrade = "PENDING";

  if (!checked || outcomeGroup === "pending") {
    grade = "PENDING";
  } else if (reaction === "trap" || (stopHit && !anyTargetHit) || outcomeGroup === "failed") {
    grade = "AVOID";
  } else if (reaction === "clean" && tp1Hit && !stopHit && !slowTarget) {
    grade = "A";
  } else if (reaction === "clean" || outcomeGroup === "worked") {
    grade = "B";
  } else if (reaction === "no_entry" || outcomeGroup === "neutral") {
    grade = "C";
  } else {
    grade = "C";
  }

  const gradeLabel =
    grade === "A"
      ? copy.gradeA
      : grade === "B"
        ? copy.gradeB
        : grade === "C"
          ? copy.gradeC
          : grade === "AVOID"
            ? copy.gradeAvoid
            : copy.gradePending;

  const reactionLabel =
    reaction === "clean"
      ? copy.reactionClean
      : reaction === "weak"
        ? copy.reactionWeak
        : reaction === "trap"
          ? copy.reactionTrap
          : reaction === "no_follow_through"
            ? copy.reactionNoFollow
            : reaction === "no_entry"
              ? copy.reactionNoEntry
              : copy.reactionPending;

  const marketVerdict =
    grade === "A"
      ? copy.verdictA
      : grade === "B"
        ? copy.verdictB
        : grade === "C"
          ? copy.verdictC
          : grade === "AVOID"
            ? copy.verdictAvoid
            : copy.verdictPending;

  const traderLesson =
    grade === "A"
      ? copy.lessonA
      : grade === "B"
        ? copy.lessonB
        : grade === "C"
          ? copy.lessonC
          : grade === "AVOID"
            ? copy.lessonAvoid
            : copy.lessonPending;

  const calibrationNote =
    grade === "A"
      ? copy.calibrationA
      : grade === "B"
        ? copy.calibrationB
        : grade === "C"
          ? copy.calibrationC
          : grade === "AVOID"
            ? copy.calibrationAvoid
            : copy.calibrationPending;

  const decision = String(alert.user_alert_decision || "").toLowerCase();
  const userActionLabel =
    linkedTrades.length > 0
      ? copy.actionLinked
      : decision === "taken"
        ? copy.actionTaken
        : decision === "missed"
          ? copy.actionMissed
          : decision === "skipped"
            ? copy.actionSkipped
            : decision === "watching"
              ? copy.actionWatching
              : copy.decisionNotMarked;

  const noLateChase = !slowEntry && !clientLateEntry;

  return {
    grade,
    gradeLabel,
    reaction,
    reactionLabel,
    entryTouched,
    tp1Hit,
    anyTargetHit,
    stopHit,
    noLateChase,
    slowEntry,
    clientLateEntry,
    marketVerdict,
    traderLesson,
    calibrationNote,
    userActionLabel,
    checked,
    isAPlus: grade === "A",
    isTrash: grade === "AVOID",
    isCleanReaction: reaction === "clean",
    isTrap: reaction === "trap",
    checkItems: [
      { label: copy.entryTouched, passed: entryTouched },
      { label: copy.tp1Hit, passed: tp1Hit },
      { label: copy.stopHit, passed: !stopHit },
      { label: copy.noLateEntry, passed: noLateChase },
    ],
  };
}

function normalizeOutcomeCheckSummary(payload: unknown): OutcomeCheckSummary {
  const row = payload && typeof payload === "object" ? (payload as Record<string, unknown>) : {};
  const items = Array.isArray(row.items) ? (row.items as Record<string, unknown>[]) : [];

  const statusOf = (item: Record<string, unknown>) =>
    String(item.status || item.outcome_status || "pending").toLowerCase();

  const worked = items.filter((item) =>
    ["worked", "tp1_hit", "tp2_hit", "tp3_hit"].includes(statusOf(item))
  ).length;

  const failed = items.filter((item) =>
    ["failed", "stopped", "stop_hit"].includes(statusOf(item))
  ).length;

  const neutral = items.filter((item) =>
    ["neutral", "no_entry", "expired_neutral"].includes(statusOf(item))
  ).length;

  const entryTouched = items.filter((item) => statusOf(item) === "entry_touched").length;
  const noCandles = items.filter((item) => Number(item.candles_checked || 0) === 0).length;
  const checked = Number(row.checked || items.length || 0);
  const resolved = worked + failed + neutral;

  return {
    checkedAt: typeof row.checkedAt === "string" ? row.checkedAt : null,
    interval: typeof row.interval === "string" ? row.interval : null,
    checked,
    updated: Number(row.updated || 0),
    events: Number(row.events || 0),
    resolved,
    entryTouched,
    noCandles,
    worked,
    failed,
    neutral,
    pending: Math.max(checked - resolved - entryTouched, 0),
  };
}

function formatOutcomePercent(value?: number | null) {
  if (typeof value !== "number" || !Number.isFinite(value)) return "вЂ”";
  return `${value >= 0 ? "+" : ""}${value.toFixed(2)}%`;
}

function formatOutcomeMinutes(value?: number | null) {
  if (typeof value !== "number" || !Number.isFinite(value)) return "вЂ”";
  if (value < 60) return `${Math.round(value)}m`;

  const hours = Math.floor(value / 60);
  const minutes = Math.round(value % 60);
  return minutes > 0 ? `${hours}h ${minutes}m` : `${hours}h`;
}

function formatOutcomeCheckedAt(value?: string | null) {
  if (!value) return "вЂ”";

  return new Intl.DateTimeFormat("ru-RU", {
    day: "2-digit",
    month: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(value));
}

