const getAlertOutcomeFollowup = (alert: DashboardMarketAlert) => {
  const decision = alert.user_alert_decision;
  const outcomeGroup = getAlertOutcomeGroup(alert);
  const outcome = getAlertOutcomeLabel(alert, safeLanguage);

  let text = copy.outcomePendingNote;
  let tone: "strong" | "warning" | "danger" | "neutral" = "neutral";

  if (outcomeGroup === "worked" && decision === "taken") {
    text = copy.outcomeTakenWorked;
    tone = "strong";
  } else if (outcomeGroup === "failed" && decision === "taken") {
    text = copy.outcomeTakenFailed;
    tone = "danger";
  } else if (outcomeGroup === "worked" && decision === "skipped") {
    text = copy.outcomeSkippedWorked;
    tone = "warning";
  } else if (outcomeGroup === "failed" && decision === "skipped") {
    text = copy.outcomeSkippedFailed;
    tone = "strong";
  } else if (outcomeGroup === "worked" && decision === "missed") {
    text = copy.outcomeMissedWorked;
    tone = "warning";
  } else if (outcomeGroup === "failed" && decision === "missed") {
    text = copy.outcomeMissedFailed;
    tone = "neutral";
  } else if (outcomeGroup === "neutral") {
    text = copy.outcomeNeutralNote;
    tone = "neutral";
  }

  return {
    decision: decision || "not marked",
    outcome,
    text,
    tone,
  };
};

